    extract_text: str = '',
    polish_text: str = ''
) -> dict:
    # 解析分类结果
    doc_type = ''
    case_nature = ''
    try:
        t = re.sub(r'<think>.*?</think>', '', classify_text or '', flags=re.DOTALL)
        t = re.sub(r'```\w*\n?', '', t)
        b1, b2 = t.find('{'), t.rfind('}')
        if b1 != -1 and b2 > b1:
            d = json.loads(t[b1:b2+1])
            doc_type = d.get('doc_type', '')
            case_nature = d.get('case_nature', '')
    except:
        pass
    # 解析要素
    elements = {}
    laws = []
    try:
        t = re.sub(r'<think>.*?</think>', '', extract_text or '', flags=re.DOTALL)
        t = re.sub(r'```\w*\n?', '', t)
        b1, b2 = t.find('{'), t.rfind('}')
        if b1 != -1 and b2 > b1:
            t = t[b1:b2+1]
        t = re.sub(r',\s*}', '}', t)
        t = re.sub(r',\s*]', ']', t)
        d = json.loads(t)
        if isinstance(d, dict):
            elements = d.get('elements', {})
            if not case_nature:
                case_nature = d.get('case_nature', '')
            laws = d.get('suggested_laws', [])
    except:
        pass
    # 推断文书类型
    if not doc_type:
        if 'crime_scene_place' in elements:
            doc_type = '现场勘查笔录'
        elif 'identification_purpose' in elements:
            doc_type = '辨认笔录'
        elif 'search_warrant_number' in elements:
            doc_type = '搜查笔录'
        elif 'seizure_duration' in elements:
            doc_type = '扣押决定书'
        elif 'inspection_target' in elements:
            doc_type = '检查笔录'
        elif 'proposed_penalty' in elements:
            doc_type = '行政处罚告知笔录'
        elif 'mediation_result' in elements:
            doc_type = '调解协议书'
        elif 'investigation_summary' in elements:
            doc_type = '结案报告'
        elif 'identification_target' in elements:
            doc_type = '指认笔录'
        else:
            doc_type = '行政处罚决定书'
    # 清理字段
    for k, v in list(elements.items()):
        if v is None or (isinstance(v, str) and v.lower() in ('null','none','无')):
            elements[k] = ''
    # 清理润色文本中的think标签
    polish_clean = re.sub(r'<think>.*?</think>', '', polish_text or '', flags=re.DOTALL).strip()
    # 替换润色后的事实
    if polish_clean:
        for fk in ['illegal_fact','case_brief','inspection_process','search_process','investigation_summary','scene_description','case_background','identification_results','dispute_description','identification_operation']:
            if fk in elements:
                elements[fk] = polish_clean
                break
    # 日期标准化
    def nd(v):
        if not v: return ''
        v = str(v).replace('年','-').replace('月','-').replace('日','').replace('时',':').replace('分','').strip()
        for f in ('%Y-%m-%d %H:%M','%Y-%m-%d %H:%M:%S','%Y-%m-%d'):
            try:
                dt = datetime.strptime(v.strip(), f)
                return dt.strftime('%Y年%m月%d日 %H时%M分') if '%H' in f else dt.strftime('%Y年%m月%d日')
            except: continue
        return str(v)
    for tk in ['inspection_time_start','inspection_time_end','identification_time_start','identification_time_end','crime_scene_time_start','crime_scene_time_end','search_time_start','search_time_end','notification_time','case_occurrence_date','penalty_decision_date','birth_date']:
        if tk in elements and elements[tk]:
            elements[tk] = nd(elements[tk])
    for dk, tk in [('inspection_date','inspection_time_start'),('identification_date','identification_time_start')]:
        if not elements.get(dk) and elements.get(tk):
            elements[dk] = nd(elements[tk])
    # 按文书类型设置默认值
    if doc_type == '检查笔录':
        if not elements.get('items_found') or str(elements['items_found']).strip() in ('无','未发现','没有'):
            elements['items_found'] = '没有发现任何涉案物品'
        if not elements.get('injury_found') or str(elements['injury_found']).strip() in ('无','未发现','没有'):
            elements['injury_found'] = '无任何损伤'
        if not elements.get('inspection_target_display') and elements.get('inspection_target'):
            elements['inspection_target_display'] = elements['inspection_target'] + '的身体'
    if doc_type == '行政处罚决定书':
        for fk in ('work_unit','criminal_record'):
            if not elements.get(fk): elements[fk] = '无'
        if not elements.get('evidence_list'):
            elements['evidence_list'] = '违法行为人的陈述和申辩、讯问笔录、被害人陈述'
        if not elements.get('penalty_basis'):
            elements['penalty_basis'] = '《中华人民共和国治安管理处罚法》第四十九条'
        if not elements.get('penalty_content'):
            elements['penalty_content'] = '行政拘留十日并处罚款五百元'
        if not elements.get('reconsideration_org'):
            elements['reconsideration_org'] = elements.get('police_station','本机关') + '的上一级公安机关'
        if not elements.get('lawsuit_court'):
            elements['lawsuit_court'] = '有管辖权的人民法院'
        if not elements.get('execution_detail'):
            elements['execution_detail'] = '收到决定书之日起15日内将罚款交到指定银行财政罚没专户。'
        if not elements.get('stamp_date'):
            today = date.today()
            cn = ['〇','一','二','三','四','五','六','七','八','九','十']
            y = ''.join(cn[int(d)] for d in str(today.year))
            m = '十' + cn[today.month%10] if today.month > 10 else ('十' if today.month==10 else cn[today.month])
            d = ''.join(cn[int(c)] if c!='0' else '' for c in str(today.day))
            elements['stamp_date'] = y + '年' + m + '月' + d + '日'
        if not elements.get('doc_number'):
            from time import time
            elements['doc_number'] = elements.get('police_station','XX')[:6].replace('公安局','').replace('分局','') + '公行罚决字[' + str(date.today().year) + ']' + str(int(time()*1000))[-6:] + '号'
    if doc_type == '行政处罚告知笔录':
        if not elements.get('evidence_list'):
            elements['evidence_list'] = '检查笔录、违法行为人的陈述和申辩，其他'
        if not elements.get('notified_person_statement'):
            elements['notified_person_statement'] = '我不提出陈述和申辩。'
    if doc_type == '辨认笔录':
        if not elements.get('identification_conclusion'):
            elements['identification_conclusion'] = '至此，辨认结束。'
        if not elements.get('identification_confirmation') and elements.get('identifier_name'):
            elements['identification_confirmation'] = '以上笔录，' + elements['identifier_name'] + '看过。'
    if doc_type == '扣押决定书':
        if not elements.get('seizure_duration'):
            elements['seizure_duration'] = '三十日'
    # 模板填充
    tpl = get_template(doc_type)
    for k, v in elements.items():
        ph = '{{' + k + '}}'
        tpl = tpl.replace(ph, str(v).strip() if v and str(v).strip().lower() not in ('none','null','') else '')
    tpl = re.sub(r'\{\{\w+\}\}', '', tpl)
    tpl = re.sub(r'\n{3,}', '\n\n', tpl)
    return {
        'content': tpl.strip(),
        'doc_type': doc_type,
        'case_nature': case_nature,
        'elements': json.dumps(elements, ensure_ascii=False, indent=2),
        'suggested_laws': chr(10).join(laws) if laws else '',
    }

